class ScriptedPolicyModel(BaseChatModel):
    """Offline scenario policy: a pure function of the conversation.

    Unlike ScriptedChatModel (fixed replay), this decides each turn from
    prior tool calls and results, so it stays aligned on resume and
    repeats. Static per scenario, so parent graphs can hold it in a
    discoverable subgraph. Still wiring verification, never model proof.
    """

    _scenario: object = PrivateAttr()

    def __init__(self, scenario: str):
        super().__init__()
        if scenario not in SCENARIOS:
            raise ValueError(f"unknown scenario {scenario!r}")
        self._scenario = scenario

    @property
    def _llm_type(self) -> str:
        return "scripted-policy"

    def bind_tools(self, tools, **kwargs):
        return self

    def _generate(self, messages, stop=None, run_manager=None, **kwargs):
        msgs = list(messages)
        return ChatResult(generations=[ChatGeneration(
            message=self._decide(msgs))])

    def _decide(self, messages):
        scenario = self._scenario
        if scenario == "arrange":
            return self._arrange(messages)
        if scenario == "deny":
            return self._deny(messages)
        return self._recover(messages)

    @staticmethod
    def _arrange(messages):
        cfg = SCENARIOS["arrange"]
        eid = "EXC-ITEM-01-1"
        steps = [
            call("get_order", {"order_id": cfg["order_id"]}),
            call("find_exchange_stock",
                 {"sku": cfg["sku"], "size": cfg["size"]}),
            call("reserve_replacement",
                 {"order_id": cfg["order_id"],
                  "order_item_id": cfg["order_item_id"], "size": cfg["size"]}),
            call("create_return", {"exchange_id": eid}),
            call("create_label", {"exchange_id": eid}),
            call("finalize_arranged", {"exchange_id": eid}),
        ]
        n = len(_tool_names(messages))
        if n < len(steps):
            return steps[n]
        return AIMessage(content="arranged")

    @staticmethod
    def _deny(messages):
        cfg = SCENARIOS["deny"]
        steps = [
            call("get_order", {"order_id": cfg["order_id"]}),
            call("reserve_replacement",
                 {"order_id": cfg["order_id"],
                  "order_item_id": cfg["order_item_id"], "size": cfg["size"]}),
            call("record_denial", {"reason": "sold as final sale"}),
        ]
        n = len(_tool_names(messages))
        if n < len(steps):
            return steps[n]
        return AIMessage(content="denied")

    @staticmethod
    def _recover(messages):
        cfg = SCENARIOS["recover"]
        eid = "EXC-ITEM-04-1"
        names = _tool_names(messages)
        if not names:
            return call("reserve_replacement",
                        {"order_id": cfg["order_id"],
                         "order_item_id": cfg["order_item_id"],
                         "size": cfg["size"]}, cid="r-crash")
        last = _last_tool_result(messages)
        if names[-1] == "reserve_replacement" and not last.get("ok"):
            op_key = last.get("op_key", "")
            return call("get_operation_status", {"op_key": op_key},
                        cid="r-status")
        if names[-1] == "get_operation_status":
            return call("reserve_replacement",
                        {"order_id": cfg["order_id"],
                         "order_item_id": cfg["order_item_id"],
                         "size": cfg["size"]}, cid="r-retry")
        if names[-1] == "reserve_replacement" and last.get("ok"):
            return call("create_return", {"exchange_id": eid}, cid="r-ret")
        if names[-1] == "create_return" and last.get("ok"):
            return call("create_label", {"exchange_id": eid}, cid="r-lab")
        if names[-1] == "create_label" and last.get("ok"):
            return call("finalize_arranged", {"exchange_id": eid}, cid="r-fin")
        return AIMessage(content="recovered and arranged")

